    out = dict(base)
    for k, v in override.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = merge(out[k], v)
        else:
            out[k] = v
    return out

def snapshot():
    return copy.deepcopy(_EFFECTIVE)

def restore(snap):
    global _EFFECTIVE
    _EFFECTIVE = copy.deepcopy(snap)

