def compute_subtotal(items):
    total = 0.0
    for it in items:
        total += it["qty"] * it["price"]
    return round(total, 2)

def apply_discount(subtotal):
    if subtotal > 200:
        return round(subtotal * (1 - 20 / 100), 2)
    return subtotal

def compute_tax(amount):
    return round(amount * 10 / 100, 2)

